class Solution:
    def spiralMatrixIII(self, rows: int, cols: int, rStart: int, cStart: int) -> list[list[int]]:
        total = rows * cols
        ans = [[rStart, cStart]]
        r, c = rStart, cStart
        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        step_len = 1; d = 0
        while len(ans) < total:
            for _ in range(2):
                dr, dc = dirs[d]
                for _ in range(step_len):
                    r += dr; c += dc
                    if 0 <= r < rows and 0 <= c < cols:
                        ans.append([r, c])
                        if len(ans) == total:
                            return ans
                d = (d + 1) % 4
            step_len += 1
        return ans

