class Solution:
    def spiralMatrixIII(self, rows: int, cols: int, rStart: int, cStart: int) -> list[list[int]]:
        ans = [[rStart, cStart]]
        r, c = rStart, cStart
        total = rows * cols
        step = 1
        while len(ans) < total:
            for dr, dc, length in ((0, 1, step), (1, 0, step), (0, -1, step + 1), (-1, 0, step + 1)):
                for _ in range(length):
                    r += dr; c += dc
                    if 0 <= r < rows and 0 <= c < cols:
                        ans.append([r, c])
                        if len(ans) == total:
                            return ans
            step += 2
        return ans

